def _install_json_logger_shim() -> None:
    """Work around a bug in the pinned xax 0.2.6 JSON logger.

    ksim 0.0.31 keeps JAX arrays in the xax training State; JsonLogger feeds
    `asdict(state)` straight into `json.dumps`, which raises TypeError and kills the
    training loop after the first logged step. Shim `json` inside that one module so
    its dumps() learns to convert arrays; everything else sees the stdlib json.
    """
    import json as _stdlib_json

    import xax.task.loggers.json as _xax_json_logger

    def _default(o: object) -> object:
        if hasattr(o, "tolist"):
            return o.tolist()
        return str(o)

    class _JsonShim:
        def __getattr__(self, name: str) -> object:
            return getattr(_stdlib_json, name)

        @staticmethod
        def dumps(data: object, **kwargs: object) -> str:
            kwargs.setdefault("default", _default)
            return _stdlib_json.dumps(data, **kwargs)

    _xax_json_logger.json = _JsonShim()  # type: ignore[attr-defined]


_install_json_logger_shim()


