class FeetechParams(TypedDict):
    sysid: str
    max_torque: float
    armature: float
    frictionloss: float
    damping: float
    vin: float
    kt: float
    R: float
    vmax: float
    amax: float
    max_velocity: float
    max_pwm: float
    error_gain: float


def trapezoidal_step(
    state: PlannerState, target_position: Array, dt: float
) -> tuple[PlannerState, tuple[Array, Array]]:
    v_max = 5.0
    a_max = 39.0

    position_error = target_position - state.position
    direction = jnp.sign(position_error)

    stopping_distance = (state.velocity**2) / (2 * a_max)

    # Decide accelerate or decelerate
    should_accelerate = jnp.abs(position_error) > stopping_distance

    acceleration = jnp.where(should_accelerate, direction * a_max, -direction * a_max)
    new_velocity = state.velocity + acceleration * dt

    # Clamp velocity
    new_velocity = jnp.clip(new_velocity, -v_max, v_max)

    # Prevent overshoot when decelerating
    new_velocity = jnp.where(direction * new_velocity < 0, 0.0, new_velocity)

    new_position = state.position + new_velocity * dt

    new_state = PlannerState(position=new_position, velocity=new_velocity)

    return new_state, (new_position, new_velocity)


def load_actuator_params(params_path: str, actuator_type: str) -> FeetechParams:
    params_file = Path(params_path) / f"{actuator_type}.json"
    if not params_file.exists():
        raise ValueError(
            f"Actuator parameters file '{params_file}' not found. Please ensure it exists in '{params_path}'."
        )
    with open(params_file, "r") as f:
        return json.load(f)


class FeetechActuators(StatefulActuators):
    """Feetech actuator controller."""

    def __init__(
        self,
        max_torque_j: Array,
        kp_j: Array,
        kd_j: Array,
        max_velocity_j: Array,
        max_pwm_j: Array,
        vin_j: Array,
        kt_j: Array,
        r_j: Array,
        vmax_j: Array,
        amax_j: Array,
        error_gain_j: Array,
        dt: float,
        action_noise: float = 0.0,
        action_noise_type: NoiseType = "none",
        torque_noise: float = 0.0,
        torque_noise_type: NoiseType = "none",
    ) -> None:
        self.max_torque_j = max_torque_j
        self.kp_j = kp_j
        self.kd_j = kd_j
        self.max_velocity_j = max_velocity_j
        self.max_pwm_j = max_pwm_j
        self.vin_j = vin_j
        self.kt_j = kt_j
        self.r_j = r_j
        self.vmax_j = vmax_j
        self.amax_j = amax_j
        self.error_gain_j = error_gain_j
        self.dt = dt
        # self.prev_qtarget_j = jnp.zeros_like(self.kp_j)
        self.action_noise = action_noise
        self.action_noise_type = action_noise_type
        self.torque_noise = torque_noise
        self.torque_noise_type = torque_noise_type

    def get_stateful_ctrl(
        self,
        action: Array,
        physics_data: PhysicsData,
        planner_state: PlannerState,
        rng: PRNGKeyArray,
    ) -> tuple[Array, PlannerState]:
        """Compute torque control with velocity smoothing and duty cycle clipping (JAX friendly)."""
        pos_rng, tor_rng = jax.random.split(rng)

        current_pos_j = physics_data.qpos[7:]
        current_vel_j = physics_data.qvel[6:]

        planner_state, (desired_position, desired_velocity) = trapezoidal_step(planner_state, action, self.dt)

        pos_error_j = desired_position - current_pos_j
        vel_error_j = desired_velocity - current_vel_j

        # Compute raw duty cycle and clip by max_pwm
        raw_duty_j = self.kp_j * self.error_gain_j * pos_error_j + self.kd_j * vel_error_j
        duty_j = jnp.clip(raw_duty_j, -self.max_pwm_j, self.max_pwm_j)

        # Compute torque
        volts_j = duty_j * self.vin_j
        torque_j = volts_j * self.kt_j / self.r_j

        # Add noise to torque
        torque_j_noisy = self.add_noise(self.torque_noise, self.torque_noise_type, torque_j, tor_rng)

        return torque_j_noisy, planner_state

    def get_default_action(self, physics_data: PhysicsData) -> Array:
        return physics_data.qpos[7:]

    def get_default_state(self, initial_position: Array, initial_velocity: Array) -> PlannerState:
        """Initialize the planner state with the provided position and velocity."""
        return PlannerState(position=initial_position, velocity=initial_velocity)


@jax.tree_util.register_dataclass
@dataclass(frozen=True)
class ServoState(PlannerState):
    """Planner state of the servo model: the setpoint (position, velocity) plus the last commands.

    buffer[0] is the newest command of the most recent physics step, buffer[k] the one k steps earlier; last_cmd is the
    rate-limited command of the previous physics step; filt the low-passed action; delay_shift the episode's random
    delay offset in physics steps (DELAY_UNSET until the first step of the episode draws it); actions the policy actions
    of the last control steps, newest first (actions[0] = the one being applied), tick the physics step count."""

    buffer: Array
    last_cmd: Array
    filt: Array
    delay_shift: Array
    actions: Array
    tick: Array


DELAY_UNSET = -(2 ** 20)


def servo_step(
    position: Array, velocity: Array, target: Array, dt: float, v_max: Array, a_max: Array
) -> tuple[Array, Array]:
    """One step of a time-optimal position servo: speed limit v_max, acceleration limit a_max.

    The setpoint moves toward `target` as fast as it may and still stops on it (no overshoot, no chatter
    around the target even for the legs' a_max of ~350 rad/s^2 at a 4 ms step)."""
    err = target - position
    v_stop = jnp.sign(err) * jnp.sqrt(2.0 * a_max * jnp.abs(err))   # fastest speed that can still stop here
    v_reach = err / dt                                              # lands exactly on the target this step
    v_des = jnp.where(jnp.abs(v_stop) < jnp.abs(v_reach), v_stop, v_reach)
    v_des = jnp.clip(v_des, -v_max, v_max)
    new_velocity = velocity + jnp.clip(v_des - velocity, -a_max * dt, a_max * dt)
    return position + new_velocity * dt, new_velocity


class ServoModelActuators(FeetechActuators):
    """FeetechActuators with the servo behaviour measured on the robot.

    The torque law is the sys-ID'd duty model of the parent (tracks the setpoint); what changes is the
    setpoint: the command first passes a per-joint delay line, then a speed- and acceleration-limited
    servo_step (STS3250 legs follow the speed register, STS3215 arms top out at ~1.8 rad/s)."""

    def __init__(self, *args, v_max_j: Array, a_max_j: Array, delay_steps_j: Array,
                 lo_j: Array | None = None, hi_j: Array | None = None, cmd_rate_j: Array | None = None,
                 filter_alpha_phys: float = 0.0, delay_rand_steps: int = 0, action_history: int = 1,
                 phys_per_ctrl: int = 1, **kwargs) -> None:
        super().__init__(*args, **kwargs)
        self.lo_j, self.hi_j = lo_j, hi_j        # the Pi clamps every policy target to the joint limits: so does the sim
        self.cmd_rate_j = cmd_rate_j             # rad/s the commanded target may move (Pi: command_rate_limit_rad_s)
        # per PHYSICS step: (1 - a)^n = (1 - alpha) over the n physics steps of one control step, so a constant action
        # is filtered exactly like the Pi does it once per control step
        self.filter_alpha_phys = float(filter_alpha_phys)
        self.v_max_j = v_max_j
        self.a_max_j = a_max_j
        self.delay_steps_j = jnp.asarray(delay_steps_j, dtype=jnp.int32)
        # per episode every delay moves by the same random shift in [-delay_rand_steps, +delay_rand_steps], at least 0
        self.delay_rand_steps = int(delay_rand_steps)
        self.buffer_len = int(jnp.max(self.delay_steps_j)) + self.delay_rand_steps + 1
        # the policy's past actions for ActionHistoryObservation (walking.py): the observation carry of this ksim version
        # is not batched per env, the planner state is. Pushed on the LAST physics step of a control step, when the
        # engine's random action latency (< 1 control step) is surely over.
        self.action_history = int(action_history)
        self.phys_per_ctrl = int(phys_per_ctrl)

    def get_default_state(self, initial_position: Array, initial_velocity: Array) -> ServoState:
        buffer = jnp.tile(initial_position[None, :], (self.buffer_len, 1))
        return ServoState(position=initial_position, velocity=initial_velocity, buffer=buffer,
                          last_cmd=initial_position, filt=initial_position,
                          delay_shift=jnp.array(DELAY_UNSET, dtype=jnp.int32),
                          actions=jnp.tile(initial_position[None, :], (self.action_history, 1)),  # = ksim's first action
                          tick=jnp.array(0, dtype=jnp.int32))

    def delays(self, delay_shift: Array) -> Array:
        """the per-joint delay in physics steps for an episode's shift"""
        return jnp.clip(self.delay_steps_j + delay_shift, 0, self.buffer_len - 1)

    def get_stateful_ctrl(
        self,
        action: Array,
        physics_data: PhysicsData,
        planner_state: PlannerState,
        rng: PRNGKeyArray,
    ) -> tuple[Array, PlannerState]:
        if not isinstance(planner_state, ServoState):   # the plain-MuJoCo render path resets with a PlannerState
            planner_state = self.get_default_state(planner_state.position, planner_state.velocity)
        delay_rng, tor_rng = jax.random.split(rng)
        drawn = jax.random.randint(delay_rng, (), -self.delay_rand_steps, self.delay_rand_steps + 1, dtype=jnp.int32)
        delay_shift = jnp.where(planner_state.delay_shift == DELAY_UNSET, drawn, planner_state.delay_shift)
        last_of_ctrl = (planner_state.tick % self.phys_per_ctrl) == self.phys_per_ctrl - 1
        actions = jnp.where(last_of_ctrl, jnp.concatenate([action[None, :], planner_state.actions[:-1]], axis=0),
                            planner_state.actions)

        # what the Pi sends: low-pass the action, clamp to the joint limits, then limit how fast the target may move
        filt = planner_state.filt
        if self.filter_alpha_phys > 0:
            filt = filt + self.filter_alpha_phys * (action - filt)
            action = filt
        cmd = action if self.lo_j is None else jnp.clip(action, self.lo_j, self.hi_j)
        if self.cmd_rate_j is not None:
            step = self.cmd_rate_j * self.dt
            cmd = planner_state.last_cmd + jnp.clip(cmd - planner_state.last_cmd, -step, step)
        buffer = jnp.concatenate([cmd[None, :], planner_state.buffer[:-1]], axis=0)
        delayed = jnp.take_along_axis(buffer, self.delays(delay_shift)[None, :], axis=0)[0]
        position, velocity = servo_step(
            planner_state.position, planner_state.velocity, delayed, self.dt, self.v_max_j, self.a_max_j
        )

        current_pos_j = physics_data.qpos[7:]
        current_vel_j = physics_data.qvel[6:]
        raw_duty_j = self.kp_j * self.error_gain_j * (position - current_pos_j) + self.kd_j * (velocity - current_vel_j)
        duty_j = jnp.clip(raw_duty_j, -self.max_pwm_j, self.max_pwm_j)
        torque_j = duty_j * self.vin_j * self.kt_j / self.r_j
        torque_j = self.add_noise(self.torque_noise, self.torque_noise_type, torque_j, tor_rng)
        return torque_j, ServoState(position=position, velocity=velocity, buffer=buffer, last_cmd=cmd, filt=filt,
                                    delay_shift=delay_shift, actions=actions, tick=planner_state.tick + 1)


def parse_center_pose(text: str) -> dict[str, float]:
    return {k.strip(): float(v) for k, v in (kv.split("=") for kv in text.split(",") if kv.strip())}


def real_joint_limits(physics_model: ksim.PhysicsModel) -> tuple[np.ndarray, np.ndarray]:
    """Per joint (MuJoCo joint order) the range the real robot may use: hardware/joint_limits.json (what the Pi clamps
    every policy target to, same angle convention as the sim) intersected with the sim joint range (which carries the
    hip_yaw_range_deg clip). Radians. Works for mujoco.MjModel and mjx.Model."""
    mappings = get_qpos_data_idxs_by_name(physics_model)
    rng = np.asarray(physics_model.jnt_range)[1:]                        # row 0 is the free base joint
    lo, hi = rng[:, 0].copy(), rng[:, 1].copy()
    real = json.load(open(Path(__file__).resolve().parents[2] / "hardware" / "joint_limits.json"))
    for name, idx in mappings.items():
        if name in real:
            i = int(idx[0]) - 7
            lo[i] = max(lo[i], np.radians(real[name]["min_deg"]))
            hi[i] = min(hi[i], np.radians(real[name]["max_deg"]))
    return lo, hi


def center_start_qpos(mj_model: mujoco.MjModel, angles_deg: dict[str, float]) -> np.ndarray:
    """Base pose (qpos[:7]) with which the real centre pose stands on both feet: base pitched until the soles lie
    flat, lowered until they touch the floor. Writes it to mj_model.qpos0[:7] and returns the joint angles (rad,
    MuJoCo joint order) that go with it.

    NEVER write joint angles into mj_model.qpos0: MuJoCo's kinematics uses qpos - qpos0, so that would move the
    joint's zero instead of the start pose. The joint angles are set by CenterPoseReset at every episode start."""
    data = mujoco.MjData(mj_model)
    joints = np.zeros(mj_model.nq - 7)
    for name, deg in angles_deg.items():
        adr = mj_model.joint(name).qposadr[0]
        joints[adr - 7] = np.radians(deg)
    feet = [g for g in range(mj_model.ngeom)
            if "Foot_collision" in (mujoco.mj_id2name(mj_model, mujoco.mjtObj.mjOBJ_GEOM, g) or "")]
    if len(feet) != 2:
        raise ValueError(f"expected 2 foot collision geoms, found {len(feet)}")

    def pose(pitch: float) -> None:
        mujoco.mj_resetData(mj_model, data)
        data.qpos[7:] = joints
        data.qpos[3:7] = [np.cos(pitch / 2), 0.0, np.sin(pitch / 2), 0.0]
        mujoco.mj_forward(mj_model, data)

    def tilt(pitch: float) -> float:
        pose(pitch)
        return float(sum(1.0 - abs(data.geom_xmat[g].reshape(3, 3)[2, 2]) for g in feet))

    lo, hi = -0.6, 0.6                                   # golden-section search: tilt() has one minimum
    for _ in range(60):
        a, b = lo + 0.382 * (hi - lo), lo + 0.618 * (hi - lo)
        lo, hi = (lo, b) if tilt(a) < tilt(b) else (a, hi)
    pitch = 0.5 * (lo + hi)
    pose(pitch)
    lowest = min(data.geom_xpos[g][2] - float(np.abs(data.geom_xmat[g].reshape(3, 3)[2]) @ mj_model.geom_size[g])
                 for g in feet)
    mj_model.qpos0[0:3] = [data.qpos[0], data.qpos[1], data.qpos[2] - lowest + 0.001]
    mj_model.qpos0[3:7] = [np.cos(pitch / 2), 0.0, np.sin(pitch / 2), 0.0]
    logger.info("start pose 'center': base pitch %.1f deg, height %.3f m", np.degrees(pitch), mj_model.qpos0[2])
    return joints


@attrs.define(frozen=True, kw_only=True)
class CenterPoseReset(ksim.Reset):
    """Episode start in the real robot's centre pose: sets the joint angles (the base pose is in qpos0)."""

    joint_qpos: tuple[float, ...] = attrs.field()

    def __call__(self, data: PhysicsData, curriculum_level: Array, rng: PRNGKeyArray) -> PhysicsData:
        new_qpos = jnp.concatenate([data.qpos[:7], jnp.array(self.joint_qpos)])
        return update_data_field(data, "qpos", new_qpos)

    @classmethod
    def from_model(cls, physics_model: ksim.PhysicsModel, center_pose_deg: str) -> "CenterPoseReset":
        """physics_model: mujoco.MjModel (tests, rendering) or mjx.Model (training: no names, no .joint())"""
        mappings = get_qpos_data_idxs_by_name(physics_model)
        joints = np.zeros(int(physics_model.nq) - 7)
        for name, deg in parse_center_pose(center_pose_deg).items():
            joints[int(mappings[name][0]) - 7] = np.radians(deg)
        return cls(joint_qpos=tuple(float(x) for x in joints))


ZbotModel = TypeVar("ZbotModel", bound=eqx.Module)


class ZbotTask(ksim.PPOTask[Config], Generic[Config, ZbotModel]):
    @property
    @abc.abstractmethod
    def get_input_shapes(self) -> list[tuple[int, ...]]:
        """Returns a list of shapes expected by the exported model's inference function."""
        raise NotImplementedError()

    def _configure_actuator_params(
        self,
        mj_model: mujoco.MjModel,
        dof_id: int,
        joint_name: str,
        params: FeetechParams,
    ) -> None:
        """Configure actuator parameters for a joint."""
        mj_model.dof_damping[dof_id] = params["damping"]
        mj_model.dof_armature[dof_id] = params["armature"]
        mj_model.dof_frictionloss[dof_id] = params["frictionloss"]
        actuator_name = f"{joint_name}_ctrl"
        actuator_id = mujoco.mj_name2id(mj_model, mujoco.mjtObj.mjOBJ_ACTUATOR, actuator_name)
        if actuator_id >= 0:
            max_torque = float(params["max_torque"])
            mj_model.actuator_forcerange[actuator_id, :] = [-max_torque, max_torque]

    def get_mujoco_model(self) -> mujoco.MjModel:
        mjcf_path = (Path(self.config.robot_urdf_path) / "robot.mjcf").resolve().as_posix()
        logger.info("Loading MJCF model from %s", mjcf_path)
        mj_model = load_mjmodel(mjcf_path, scene="smooth")

        metadata = self.get_mujoco_model_metadata(mj_model)

        mj_model.opt.timestep = jnp.array(self.config.dt)
        mj_model.opt.iterations = 6
        mj_model.opt.ls_iterations = 6
        mj_model.opt.disableflags = mjx.DisableBit.EULERDAMP
        mj_model.opt.solver = mjx.SolverType.CG

        # Validate parameters
        required_keys = ["damping", "armature", "frictionloss", "max_torque"]

        # Apply servo-specific parameters based on joint metadata
        for i in range(mj_model.njnt):
            joint_name = mujoco.mj_id2name(mj_model, mujoco.mjtObj.mjOBJ_JOINT, i)
            if joint_name is None:
                logger.warning("Joint at index %d has no name; skipping parameter assignment.", i)
                continue

            # Look up joint metadata. Warn if actuator_type is missing.
            if joint_name not in metadata:
                logger.warning("Joint '%s' is missing; skipping parameter assignment.", joint_name)
                continue

            joint_meta = metadata[joint_name]
            if joint_meta.actuator_type is None:
                logger.warning("Joint '%s' is missing an actuator_type; skipping parameter assignment.", joint_name)
                continue

            dof_id = mj_model.jnt_dofadr[i]

            # Load and validate parameters for this actuator type
            params = load_actuator_params(self.config.actuator_params_path, joint_meta.actuator_type)
            for key in required_keys:
                if key not in params:
                    raise ValueError(f"Missing required key '{key}' in {joint_meta.actuator_type} parameters.")

            # Apply parameters based on the joint suffix
            self._configure_actuator_params(mj_model, dof_id, joint_name, params)

        if self.config.hip_yaw_range_deg > 0:
            lim = np.radians(self.config.hip_yaw_range_deg)
            for i in range(mj_model.njnt):
                name = mujoco.mj_id2name(mj_model, mujoco.mjtObj.mjOBJ_JOINT, i)
                if name and "hip_yaw" in name:
                    mj_model.jnt_range[i] = np.clip(mj_model.jnt_range[i], -lim, lim)
                    logger.info("%s range clipped to %s deg", name, np.degrees(mj_model.jnt_range[i]).round(1))
        if self.config.start_pose == "center":
            center_start_qpos(mj_model, parse_center_pose(self.config.center_pose_deg))
        elif self.config.start_pose != "zero":
            raise ValueError(f"start_pose must be 'zero' or 'center', not '{self.config.start_pose}'")

        return mj_model

    def log_joint_config(self, model: Union[mujoco.MjModel, mjx.Model]) -> None:
        metadata = self.get_mujoco_model_metadata(model)
        debug_lines = ["==== Joint and Actuator Properties ===="]

        if isinstance(model, mujoco.MjModel):
            logger.info("******** PhysicsModel is Mujoco")

            njnt = model.njnt

            def get_joint_name(idx: int) -> Optional[str]:
                return mujoco.mj_id2name(model, mujoco.mjtObj.mjOBJ_JOINT, idx)

            def get_actuator_id(name: str) -> int:
                return mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, name)

            dof_damping = model.dof_damping
            dof_armature = model.dof_armature
            dof_frictionloss = model.dof_frictionloss
            jnt_dofadr = model.jnt_dofadr
            actuator_forcerange = model.actuator_forcerange

        elif isinstance(model, mjx.Model):
            logger.info("******** PhysicsModel is MJX")

            njnt = model.njnt
            dof_damping = model.dof_damping
            dof_armature = model.dof_armature
            dof_frictionloss = model.dof_frictionloss
            jnt_dofadr = model.jnt_dofadr
            actuator_forcerange = model.actuator_forcerange

            def extract_name(byte_array: bytes, adr_array: Sequence[int], idx: int) -> Optional[str]:
                adr = adr_array[idx]
                if adr < 0:
                    return None
                end = byte_array.find(b"\x00", adr)
                return byte_array[adr:end].decode("utf-8")

            actuator_name_to_id = {
                extract_name(model.names, model.name_actuatoradr, i): i
                for i in range(model.nu)
                if model.name_actuatoradr[i] >= 0
            }

            def get_joint_name(idx: int) -> Optional[str]:
                return extract_name(model.names, model.name_jntadr, idx)

            def get_actuator_id(name: str) -> int:
                return actuator_name_to_id.get(name, -1)

        else:
            raise TypeError("Unsupported model type provided")

        for i in range(njnt):
            joint_name = get_joint_name(i)
            if joint_name is None:
                continue

            joint_meta = metadata.get(joint_name)
            if not joint_meta:
                logger.warning("Joint '%s' missing metadata; skipping.", joint_name)
                continue

            actuator_type = joint_meta.actuator_type
            if actuator_type is None:
                logger.warning("Joint '%s' missing actuator_type; skipping.", joint_name)
                continue

            dof_id = jnt_dofadr[i]
            damping = dof_damping[dof_id]
            armature = dof_armature[dof_id]
            frictionloss = dof_frictionloss[dof_id]
            joint_id = joint_meta.id if joint_meta.id is not None else "N/A"
            kp = joint_meta.kp if joint_meta.kp is not None else "N/A"
            kd = joint_meta.kd if joint_meta.kd is not None else "N/A"

            actuator_name = f"{joint_name}_ctrl"
            actuator_id = get_actuator_id(actuator_name)

            line = (
                f"Joint: {joint_name:<20} | Joint ID: {joint_id!s:<3} | "
                f"Damping: {damping:6.3f} | Armature: {armature:6.3f} | "
                f"Friction: {frictionloss:6.3f}"
            )

            if actuator_id >= 0:
                forcerange = actuator_forcerange[actuator_id]
                line += (
                    f" | Actuator: {actuator_name:<20} (ID: {actuator_id:2d}) | "
                    f"Forcerange: [{forcerange[0]:6.3f}, {forcerange[1]:6.3f}] | "
                    f"Kp: {kp} | Kd: {kd}"
                )
            else:
                line += " | Actuator: N/A (passive joint)"

            debug_lines.append(line)

        logger.info("\n".join(debug_lines))

    def get_mujoco_model_metadata(self, mj_model: mujoco.MjModel) -> dict[str, JointMetadataOutput]:
        """Get joint metadata from metadata.json file."""
        metadata_path = Path(self.config.robot_urdf_path) / "metadata.json"
        if not metadata_path.exists():
            raise FileNotFoundError(f"Metadata file not found at {metadata_path}")
        try:
            with open(metadata_path, "r") as f:
                raw_metadata = json.load(f)
        except json.JSONDecodeError as e:
            raise ValueError(f"Error decoding JSON from {metadata_path}: {e}")

        if "joint_name_to_metadata" not in raw_metadata:
            raise ValueError(f"'joint_name_to_metadata' key missing in {metadata_path}")

        joint_metadata = raw_metadata["joint_name_to_metadata"]
        if not isinstance(joint_metadata, dict):
            raise TypeError(f"'joint_name_to_metadata' in {metadata_path} must be a dictionary.")

        # Convert raw metadata to JointMetadataOutput objects
        return {joint_name: JointMetadataOutput(**metadata) for joint_name, metadata in joint_metadata.items()}

    def get_actuators(
        self,
        physics_model: ksim.PhysicsModel,
        metadata: dict[str, JointMetadataOutput] | None = None,
    ) -> ksim.Actuators:
        if metadata is None:
            raise ValueError("Metadata is required to get actuators")

        self.joint_mappings = self.create_joint_mappings(physics_model, metadata)

        num_joints = len(self.joint_mappings)

        max_torque_j = jnp.zeros(num_joints)
        max_velocity_j = jnp.zeros(num_joints)
        max_pwm_j = jnp.zeros(num_joints)
        vin_j = jnp.zeros(num_joints)
        kt_j = jnp.zeros(num_joints)
        r_j = jnp.zeros(num_joints)
        # vmax_j = jnp.zeros(num_joints)
        # amax_j = jnp.zeros(num_joints)
        vmax_j = jnp.ones(num_joints) * 5.0  # or whatever test value you want
        amax_j = jnp.ones(num_joints) * 39.0
        kp_j = jnp.zeros(num_joints)
        kd_j = jnp.zeros(num_joints)
        error_gain_j = jnp.zeros(num_joints)

        # Validate parameters
        required_keys = ["max_torque", "error_gain", "max_velocity", "max_pwm", "vin", "kt", "R"]

        # Order by MuJoCo joint order (nn_id): the ctrl vector the physics engine consumes
        # is in MuJoCo actuator order, which in our MJCF equals joint order. Sorting by
        # servo id (upstream behavior) scrambles per-joint parameters for this build.
        sorted_joints = sorted(self.joint_mappings.items(), key=lambda x: x[1]["nn_id"])
        is_arm_j = [False] * num_joints

        for i, (joint_name, mapping) in enumerate(sorted_joints):
            joint_metadata = metadata[joint_name]
            if not isinstance(joint_metadata, JointMetadataOutput):
                raise TypeError(f"Metadata entry for joint '{joint_name}' must be a JointMetadataOutput.")

            actuator_type = cast(str, joint_metadata.actuator_type)
            if actuator_type is None:
                raise ValueError(f"'actuator_type' is not available for joint {joint_name}")
            if not isinstance(actuator_type, str):
                raise TypeError(f"'actuator_type' for joint {joint_name} must be a string.")
            is_arm_j[i] = "3215" in actuator_type          # STS3215 = arms, STS3250 = legs

            params = load_actuator_params(self.config.actuator_params_path, actuator_type)

            # Validate parameters
            for key in required_keys:
                if key not in params:
                    raise ValueError(f"Missing required key '{key}' in {actuator_type} parameters.")

            max_torque_j = max_torque_j.at[i].set(params["max_torque"])
            max_velocity_j = max_velocity_j.at[i].set(params["max_velocity"])
            max_pwm_j = max_pwm_j.at[i].set(params["max_pwm"])
            vin_j = vin_j.at[i].set(params["vin"])
            kt_j = kt_j.at[i].set(params["kt"])
            r_j = r_j.at[i].set(params["R"])
            error_gain_j = error_gain_j.at[i].set(params["error_gain"])

            # Set kp and kd values
            if joint_metadata.kp is None or joint_metadata.kd is None:
                raise ValueError(f"kp/kd values for joint {joint_name} are not available")
            kp_j = kp_j.at[i].set(float(joint_metadata.kp))
            kd_j = kd_j.at[i].set(float(joint_metadata.kd))

        self.log_joint_config(physics_model)

        if self.config.servo_model:
            import math

            if self.config.servo_kp > 0:
                kp_j = jnp.full_like(kp_j, self.config.servo_kp)

            arm = jnp.array(is_arm_j)
            leg_v = self.config.leg_servo_speed * 2.0 * math.pi / 4096.0
            delay_s = jnp.where(arm, self.config.arm_delay, self.config.leg_delay)
            logger.info("servo model: legs v_max %.2f rad/s a_max %.0f delay %.0f ms | arms v_max %.2f a_max %.1f "
                        "delay %.0f ms", leg_v, self.config.leg_a_max, self.config.leg_delay * 1000,
                        self.config.arm_v_max, self.config.arm_a_max, self.config.arm_delay * 1000)
            return ServoModelActuators(
                max_torque_j=max_torque_j,
                max_velocity_j=max_velocity_j,
                max_pwm_j=max_pwm_j,
                vin_j=vin_j,
                kt_j=kt_j,
                r_j=r_j,
                kp_j=kp_j,
                kd_j=kd_j,
                vmax_j=vmax_j,
                amax_j=amax_j,
                dt=self.config.dt,
                error_gain_j=error_gain_j,
                action_noise=0.0,
                action_noise_type="none",
                torque_noise=0.0,
                torque_noise_type="none",
                v_max_j=jnp.where(arm, self.config.arm_v_max, leg_v),
                a_max_j=jnp.where(arm, self.config.arm_a_max, self.config.leg_a_max),
                delay_steps_j=jnp.round(delay_s / self.config.dt).astype(jnp.int32),
                **({"lo_j": jnp.array(real_joint_limits(physics_model)[0]),
                    "hi_j": jnp.array(real_joint_limits(physics_model)[1])} if self.config.clamp_to_real_limits else {}),
                **({"cmd_rate_j": self.config.cmd_rate_fraction * jnp.where(arm, self.config.arm_v_max, leg_v)}
                   if self.config.cmd_rate_fraction > 0 else {}),
                filter_alpha_phys=(1.0 - (1.0 - self.config.action_filter_alpha) ** (self.config.dt / self.config.ctrl_dt)
                                   if self.config.action_filter_alpha > 0 else 0.0),
                delay_rand_steps=int(round(self.config.delay_rand / self.config.dt)),
                action_history=int(getattr(self.config, "action_history", 1)),
                phys_per_ctrl=int(round(self.config.ctrl_dt / self.config.dt)),
            )

        return FeetechActuators(
            max_torque_j=max_torque_j,
            max_velocity_j=max_velocity_j,
            max_pwm_j=max_pwm_j,
            vin_j=vin_j,
            kt_j=kt_j,
            r_j=r_j,
            kp_j=kp_j,
            kd_j=kd_j,
            vmax_j=vmax_j,
            amax_j=amax_j,
            dt=self.config.dt,
            error_gain_j=error_gain_j,
            action_noise=0.0,
            action_noise_type="none",
            torque_noise=0.0,
            torque_noise_type="none",
        )

    def make_export_model(self, model: ZbotModel, stochastic: bool = False, batched: bool = False) -> Callable:
        """Makes a callable inference function that directly takes a flattened input vector and returns an action.

        Returns:
            A tuple containing the inference function and the size of the input vector.
        """
        # Cast model to the expected type to satisfy MyPy
        if not hasattr(model, "actor") or not hasattr(model.actor, "call_flat_obs"):
            raise TypeError("Model passed to make_export_model must have actor with call_flat_obs method.")

        def deterministic_model_fn(obs: Array) -> Array:
            # Use the cast model
            return model.actor.call_flat_obs(obs).mode()

        def stochastic_model_fn(obs: Array) -> Array:
            # Use the cast model
            distribution = model.actor.call_flat_obs(obs)
            return distribution.sample(seed=jax.random.PRNGKey(0))

        if stochastic:
            model_fn = stochastic_model_fn
        else:
            model_fn = deterministic_model_fn

        if batched:

            def batched_model_fn(obs: Array) -> Array:
                return jax.vmap(model_fn)(obs)

            return batched_model_fn

        return model_fn

    def on_after_checkpoint_save(self, ckpt_path: Path, state: xax.State | None) -> xax.State | None:
        if state is None:
            return None

        state = super().on_after_checkpoint_save(ckpt_path, state)

        model: ZbotModel = self.load_ckpt(ckpt_path, part="model")

        model_fn = self.make_export_model(model, stochastic=False, batched=True)

        input_shapes: list[tuple[int, ...]] = self.get_input_shapes

        export(
            model_fn,
            input_shapes,
            ckpt_path.parent / "tf_model",
        )

        return state

    def create_joint_mappings(
        self, physics_model: ksim.PhysicsModel, metadata: dict[str, JointMetadataOutput]
    ) -> dict[str, dict]:
        """Creates mappings between joint names, nn_ids, and actuator_ids.

        Args:
            physics_model: The MuJoCo/MJX model containing joint information
            metadata: The joint metadata dictionary from metadata.json

        Returns:
            Dictionary mapping joint names to their nn_id and actuator_id
        """
        debug_lines = ["==== Joint Name to ID Mappings ===="]

        # Get ordered list of joints from MuJoCo/MJX model
        if isinstance(physics_model, mujoco.MjModel):
            mujoco_joints = [
                mujoco.mj_id2name(physics_model, mujoco.mjtObj.mjOBJ_JOINT, i)
                for i in range(physics_model.njnt)
                if mujoco.mj_id2name(physics_model, mujoco.mjtObj.mjOBJ_JOINT, i) is not None
            ]
        else:  # MJX model

            def extract_joint_name(model: mjx.Model, idx: int) -> Optional[str]:
                adr = model.name_jntadr[idx]
                if adr < 0:
                    return None
                end = model.names.find(b"\x00", adr)
                return model.names[adr:end].decode("utf-8")

            mujoco_joints = [
                name for i in range(physics_model.njnt) if (name := extract_joint_name(physics_model, i)) is not None
            ]

        # Create mappings using joint names as keys
        joint_mappings = {}

        # Map each joint, using MuJoCo order for nn_ids
        for nn_id, joint_name in enumerate(mujoco_joints):
            if joint_name in metadata:
                actuator_id = metadata[joint_name].id
                if actuator_id is None:
                    logger.warning("Joint %s has no actuator id", joint_name)
                joint_mappings[joint_name] = {"nn_id": nn_id, "actuator_id": actuator_id}

                debug_lines.append("%-30s -> nn_id: %2d, actuator_id: %s" % (joint_name, nn_id, str(actuator_id)))
            else:
                logger.warning("Joint %s not found in metadata", joint_name)

        logger.info("\n".join(debug_lines))
        return joint_mappings
